import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 单元 3 复习与自测 · 第41–51课","description":"L41–L60 原创练习和答案解析。","frontmatter":{"title":"第三册：培养技能 · 单元 3 复习与自测 · 第41–51课","description":"L41–L60 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-3/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 3 复习与自测","summary":"L41–L60 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 3 复习与自测","link":"/life/english/new-concept/book-3/unit-03/review"},"next":{"text":"第三册：培养技能 · 单元 3 复习与自测 · 第52–60课","link":"/life/english/new-concept/book-3/unit-03/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 3 复习与自测","link":"/life/english/new-concept/book-3/unit-03/review"},"next":{"text":"第三册：培养技能 · 单元 3 复习与自测 · 第52–60课","link":"/life/english/new-concept/book-3/unit-03/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/review-part-01.md","filePath":"life/english/new-concept/book-3/unit-03/review-part-01.md"}'),r={name:"life/english/new-concept/book-3/unit-03/review-part-01.md"};function n(l,e,i,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-单元-3-复习与自测-·-第41–51课" tabindex="-1">第三册：培养技能 · 单元 3 复习与自测 · 第41–51课 <a class="header-anchor" href="#第三册-培养技能-·-单元-3-复习与自测-·-第41–51课" aria-label="Permalink to &quot;第三册：培养技能 · 单元 3 复习与自测 · 第41–51课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第三册-培养技能-·-单元-3-复习与自测" tabindex="-1">第三册：培养技能 · 单元 3 复习与自测 <a class="header-anchor" href="#第三册-培养技能-·-单元-3-复习与自测" aria-label="Permalink to &quot;第三册：培养技能 · 单元 3 复习与自测 {#第三册-培养技能-·-单元-3-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-41-·-while-与-whereas-的对照" tabindex="-1">Lesson 41 · while 与 whereas 的对照 <a class="header-anchor" href="#lesson-41-·-while-与-whereas-的对照" aria-label="Permalink to &quot;Lesson 41 · while 与 whereas 的对照 {#lesson-41-·-while-与-whereas-的对照}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>例句比较的是交通还是夜间活动？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 夜间活动。</p><p><strong>解析：</strong> quiet after sunset 与 busy until midnight 是对应信息。</p></details><p><strong>表达迁移：</strong> 比较两种居住环境，用三句写出同一维度的差异与个人取舍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The city flat is close to work, whereas the cottage requires a long drive. The cottage offers more outdoor space. For now, a shorter commute matters more to me.</p><p>先比较通勤，再补充空间，最后说明个人权重而非普遍优劣。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">回看本课</a></p><h2 id="lesson-42-·-独立主格的独立主语" tabindex="-1">Lesson 42 · 独立主格的独立主语 <a class="header-anchor" href="#lesson-42-·-独立主格的独立主语" aria-label="Permalink to &quot;Lesson 42 · 独立主格的独立主语 {#lesson-42-·-独立主格的独立主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The main passage blocked, the team returned to the entrance.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>把例句改为 because 从句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because the main passage was blocked, the team returned to the entrance.</p><p><strong>解析：</strong> 恢复明确主语和限定谓语。</p></details><p><strong>表达迁移：</strong> 用三句写虚构地下通道检查，包含环境变化和团队决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our spare lights ready, we entered the first chamber. Water soon covered the lower steps. We returned before the rising level blocked the exit.</p><p>独立结构说明准备状态，后两句给出观察和及时调整。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">回看本课</a></p><h2 id="lesson-43-·-provided-that-与-unless" tabindex="-1">Lesson 43 · provided that 与 unless <a class="header-anchor" href="#lesson-43-·-provided-that-与-unless" aria-label="Permalink to &quot;Lesson 43 · provided that 与 unless {#lesson-43-·-provided-that-与-unless}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>虚构规则允许两周后首次报告吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不允许据此获得所述保障。</p><p><strong>解析：</strong> 条件明确为一周内报告。</p></details><p><strong>表达迁移：</strong> 为虚构物品借用制度写三句，明确保障、条件和例外。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The club will repair borrowed lamps if faults are reported promptly. Batteries are not included in this promise. Members should photograph the damage before returning a lamp.</p><p>规则结果、例外和操作建议分开，避免把一般说明读成无限承诺。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">回看本课</a></p><h2 id="lesson-44-·-平行结构与-not-only" tabindex="-1">Lesson 44 · 平行结构与 not only <a class="header-anchor" href="#lesson-44-·-平行结构与-not-only" aria-label="Permalink to &quot;Lesson 44 · 平行结构与 not only {#lesson-44-·-平行结构与-not-only}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>例句 both ... and 连接什么类型成分？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两个名词短语。</p><p><strong>解析：</strong> a quiet place 与 a direct route 都是 offers 的宾语。</p></details><p><strong>表达迁移：</strong> 比较两种虚构通勤方案，用三句说明总时间和舒适度。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The express bus is faster on the main road. However, the local train takes me directly to the office district. It offers both predictable travel time and a seat where I can read.</p><p>局部速度与全程便利分开比较，两个优点以平行名词短语呈现。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">回看本课</a></p><h2 id="lesson-45-·-报告动词及其结构" tabindex="-1">Lesson 45 · 报告动词及其结构 <a class="header-anchor" href="#lesson-45-·-报告动词及其结构" aria-label="Permalink to &quot;Lesson 45 · 报告动词及其结构 {#lesson-45-·-报告动词及其结构}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>例句中“更广泛的问题”是谁的判断？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 倡议者的判断。</p><p><strong>解析：</strong> claimed that 明确归属。</p></details><p><strong>表达迁移：</strong> 写三句报道摘要，区分观察、引用和未证实内容。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The newspaper published photographs of the damaged bridge. Residents said that repairs had been delayed. The council has not yet confirmed the proposed reopening date.</p><p>可见材料、居民说法、机构尚未确认分别标注，避免混成一个确定结论。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">回看本课</a></p><h2 id="lesson-46-·-过去能力与一次成功" tabindex="-1">Lesson 46 · 过去能力与一次成功 <a class="header-anchor" href="#lesson-46-·-过去能力与一次成功" aria-label="Permalink to &quot;Lesson 46 · 过去能力与一次成功 {#lesson-46-·-过去能力与一次成功}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> After several careful attempts, I managed to remove the damaged screw.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>例句螺丝是否最终取出？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 是。</p><p><strong>解析：</strong> managed to 明确实际成功。</p></details><p><strong>表达迁移：</strong> 用三句写一次低风险物品组装经历，说明困难和处理结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I could assemble simple shelves, but this kit had unclear labels. After sorting the parts by size, I managed to fit the frame together. I left the final wall mounting to an experienced installer.</p><p>一般能力、具体成功和能力边界各自清楚，不把部分成功说成全部完成。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">回看本课</a></p><h2 id="lesson-47-·-because、therefore-与因果关系" tabindex="-1">Lesson 47 · because、therefore 与因果关系 <a class="header-anchor" href="#lesson-47-·-because、therefore-与因果关系" aria-label="Permalink to &quot;Lesson 47 · because、therefore 与因果关系 {#lesson-47-·-because、therefore-与因果关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>例句 therefore 前为何不用普通逗号直接拼接？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两侧都是完整分句。</p><p><strong>解析：</strong> 连接副词本身不能充当并列连词。</p></details><p><strong>表达迁移：</strong> 用三句评价一个虚构便利设施的代价，列出观察和改进建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new delivery entrance saves workers time. However, metal carts wake nearby residents before dawn. Rubber wheels and later collection hours may reduce the disturbance.</p><p>便利与代价均具体，may 避免对改进效果作未经测试的保证。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">回看本课</a></p><h2 id="lesson-48-·-地点前置的完全倒装" tabindex="-1">Lesson 48 · 地点前置的完全倒装 <a class="header-anchor" href="#lesson-48-·-地点前置的完全倒装" aria-label="Permalink to &quot;Lesson 48 · 地点前置的完全倒装 {#lesson-48-·-地点前置的完全倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Beyond the empty square stood a row of houses with closed shutters.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>还原例句为普通语序。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A row of houses with closed shutters stood beyond the empty square.</p><p><strong>解析：</strong> 把主语移回谓语前，地点置后。</p></details><p><strong>表达迁移：</strong> 用三句描绘一处安静场景，包含一个倒装句并避免臆断。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At the end of the lane stood an empty bus shelter. No voices came from the nearby houses. We could not tell whether the residents were away or simply indoors.</p><p>倒装建立空间，最后一句主动限制对静默的解释。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">回看本课</a></p><h2 id="lesson-49-·-介词加关系代词" tabindex="-1">Lesson 49 · 介词加关系代词 <a class="header-anchor" href="#lesson-49-·-介词加关系代词" aria-label="Permalink to &quot;Lesson 49 · 介词加关系代词 {#lesson-49-·-介词加关系代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The assistant on whom the household relied kept a careful record of every delivery.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>把例句的关系从句改为介词留末尾的形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The assistant whom the household relied on kept a careful record of every delivery.</p><p><strong>解析：</strong> on 移到 relied 后，whom 也可省略。</p></details><p><strong>表达迁移：</strong> 用三句说明一位虚构助手的可靠性，给出可观察行为。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The coordinator on whom we rely checks every booking twice. She also explains changes before they affect visitors. Clear communication matters more to us than a flawless appearance.</p><p>具体行动支撑可靠评价，最后一句明确价值标准。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-动词后-ing-与-to-do-的意义" tabindex="-1">Lesson 50 · 动词后 ing 与 to do 的意义 <a class="header-anchor" href="#lesson-50-·-动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;Lesson 50 · 动词后 ing 与 to do 的意义 {#lesson-50-·-动词后-ing-与-to-do-的意义}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I stopped checking messages during study sessions and tried leaving my phone in another room.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>翻译：记得关灯。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Remember to turn off the light.</p><p><strong>解析：</strong> 提醒执行尚需完成的动作。</p></details><p><strong>表达迁移：</strong> 用三句写一个可检验的学习习惯计划，包含试验和复盘。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I will read for ten minutes after breakfast. If I keep forgetting, I will try leaving the book beside my cup. At the end of the week, I will count the days I actually read.</p><p>时间触发、环境提示和反馈指标完整，比抽象决心更可执行。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-将来完成时的截止视角" tabindex="-1">Lesson 51 · 将来完成时的截止视角 <a class="header-anchor" href="#lesson-51-·-将来完成时的截止视角" aria-label="Permalink to &quot;Lesson 51 · 将来完成时的截止视角 {#lesson-51-·-将来完成时的截止视角}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the schedule holds, the team will have tested all three models by Friday.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>例句保证任何情况下都能周五完成吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不保证。</p><p><strong>解析：</strong> if the schedule holds 是明确条件。</p></details><p><strong>表达迁移：</strong> 用三句对虚构项目作谨慎预测，包含依据、截止点和不确定因素。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The first two trials took one day each. If the remaining trials follow that pattern, we will have finished by Thursday. Unexpected equipment faults could still change the schedule.</p><p>以观察到的模式作条件预测，再指出模式可能失效的因素。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-051">回看本课</a></p>',95)])])}const m=s(r,[["render",n]]);export{u as __pageData,m as default};
